import "core-js/modules/esnext.iterator.map.js";
import maplibregl from 'maplibre-gl'; // Nhớ cài đặt maplibre-gl

export default {
  props: {
    selectedLocation: {
      type: Array,
      default: () => [105.85242472181584, 21.029579719995272]
    }
  },
  data() {
    return {
      map: null,
      apiUrl: 'https://rsapi.goong.io',
      mapUrl: 'https://tiles.goong.io/assets/',
      apiKey: 'ArPlUISaEBAdJFTABi9dcNGcue8WQ4cOAuGcNoBE',
      // your API key
      mapKey: 'tLyW2vk0aY3yfQLu8ZPy986mAgaW8igMYufv3BLY',
      // your map key
      center: [105.85242472181584, 21.029579719995272],
      // Kinh độ, vĩ độ
      zoom: 14 // Độ zoom mặc định
    };
  },
  mounted() {
    this.initMap();
  },
  watch: {
    selectedLocation: 'moveToLocation' // Theo dõi thay đổi tọa độ
  },
  methods: {
    initMap() {
      this.map = new maplibregl.Map({
        container: 'map',
        style: `${this.mapUrl}goong_map_web.json?api_key=${this.mapKey}`,
        center: this.selectedLocation,
        zoom: 14
      });
    },
    moveToLocation(newLocation) {
      this.map.flyTo({
        center: newLocation,
        essential: true
      });
      this.addMarkerAndCircleAround(newLocation);
    },
    addMarkerAndCircleAround(lngLat) {
      // Xóa các marker và vòng tròn cũ nếu có
      this.map.eachLayer(layer => {
        if (layer.id === 'marker' || layer.id === 'circle') {
          this.map.removeLayer(layer.id);
          this.map.removeSource(layer.id);
        }
      });

      // Thêm marker
      new maplibregl.Marker({
        id: 'marker'
      }).setLngLat(lngLat).addTo(this.map);

      // Thêm vòng tròn
      const radiusInMeters = 100; // Đường kính vòng tròn
      const circle = {
        type: 'FeatureCollection',
        features: [{
          type: 'Feature',
          properties: {},
          geometry: {
            type: 'Point',
            coordinates: lngLat
          }
        }]
      };
      this.map.addSource('circle', {
        type: 'geojson',
        data: circle
      });
      this.map.addLayer({
        id: 'circle',
        type: 'circle',
        source: 'circle',
        paint: {
          'circle-radius': radiusInMeters / 100,
          // Chuyển đổi mét thành pixel
          'circle-color': '#FF0000',
          'circle-opacity': 0.5
        }
      });
    }
  }
};
